const nitEmisor = String($input.first().json.query.nitEmisor || '').replace(/\D/g, '');
if (!nitEmisor) {
  throw new Error('Falta el parámetro nitEmisor en la consulta.');
}
return [{ json: { nitEmisor } }];

// Consulta por partes: si el panel vuelve a preguntar trae jobId/location (solo letras, números, - y _).
const _qp = $('Webhook: correos pagadores').first().json.query || {};
const _jobId = String(_qp.jobId || '').replace(/[^A-Za-z0-9_-]/g, '');
const _location = String(_qp.location || '').replace(/[^A-Za-z0-9-]/g, '') || 'us-east1';
const nitEmisor = $input.first().json.nitEmisor;
// Solo los correos de notificación de cada pagador del cliente (mapping_rules). No toca los demás flujos.
const bqQuery = 'SELECT nit_contraparte, razon_social_contraparte, correos_notificacion ' +
  'FROM `inlaid-stack-375114.analytics_data_products.mapping_rules`' +
  " WHERE nit_cliente = '" + nitEmisor + "' AND nit_contraparte IS NOT NULL";
return [{ json: { jobId: _jobId, location: _location, nitEmisor, bqQuery } }];

// Consulta por partes: BigQuery aún no termina -> el panel vuelve a preguntar con este jobId.
const _r = $input.first().json || {};
if (_r.jobComplete === false && _r.jobReference && _r.jobReference.jobId) {
  return [{ json: { pendiente: true, jobId: _r.jobReference.jobId, location: _r.jobReference.location || 'us-east1' } }];
}
const fields = (_r.schema && _r.schema.fields) || [];
const rows = (_r.rows || []).map(row => { const o = {}; row.f.forEach((c, i) => { o[fields[i].name] = c.v; }); return o; });

// El campo viene escrito a mano: se separa por coma, punto y coma, espacios, " - " o "CC".
// Correo válido = formato normal, sin tildes ni dominio repetido (.com.com). Lo demás queda como "revisar".
const VALIDO = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/;
function limpiar(texto){
  const piezas = String(texto == null ? '' : texto)
    .split(/[\s,;]+|\bCC\b/i)
    .map(p => p.replace(/^["'<(\[]+|["'>)\].]+$/g, '').trim())
    .filter(p => p && p !== '-' && p.includes('@'));
  const validos = [], revisar = [];
  piezas.forEach(p => {
    const malo = !VALIDO.test(p) || /\.(com|co|net|org)\.\1$/i.test(p);
    const lista = malo ? revisar : validos;
    if (!lista.some(x => x.toLowerCase() === p.toLowerCase())) lista.push(p);
  });
  return { validos, revisar };
}

const pagadores = {};
rows.forEach(r => {
  const nit = String(r.nit_contraparte || '').replace(/\D/g, '');
  if (!nit) return;
  const c = limpiar(r.correos_notificacion);
  const prev = pagadores[nit] || { razonSocial: r.razon_social_contraparte || '', validos: [], revisar: [] };
  c.validos.forEach(x => { if (!prev.validos.includes(x)) prev.validos.push(x); });
  c.revisar.forEach(x => { if (!prev.revisar.includes(x)) prev.revisar.push(x); });
  pagadores[nit] = prev;
});
return [{ json: { encontrado: rows.length > 0, pagadores } }];
